tape( 'the function returns `NaN` if provided a `NaN`', opts, function test( t ) {
	var v = sinhf( NaN );
	t.strictEqual( isnanf( v ), true, 'returns expected value' );
	t.end();
});

tape( 'the function returns `-0` if provided `-0`', opts, function test( t ) {
	var v = sinhf( -0.0 );
	t.strictEqual( isNegativeZerof( v ), true, 'returns expected value' );
	t.end();
});

tape( 'the function returns `0` if provided `0`', opts, function test( t ) {
	var v = sinhf( 0.0 );
	t.strictEqual( isPositiveZerof( v ), true, 'returns expected value' );
	t.end();
});

tape( 'the function returns `+infinity` if provided `+infinity`', opts, function test( t ) {
	var v = sinhf( PINF );
	t.strictEqual( v, PINF, 'returns expected value' );
	t.end();
});

tape( 'the function returns `-infinity` if provided `-infinity`', opts, function test( t ) {
	var v = sinhf( NINF );
	t.strictEqual( v, NINF, 'returns expected value' );
	t.end();
});

tape( 'the function returns `+infinity` if provided a value greater than `MAXLOGF`', opts, function test( t ) {
	var y;
	var v;
	var i;

	for ( i = 0; i < 500; i++ ) {
		v = f32( ( randu()*1e3 ) + MAXLOGF );
		y = sinhf( v );
		t.strictEqual( y, PINF, 'returns expected value' );
	}
	t.end();
});

tape( 'the function returns `-infinity` if provided a value less than `~-MAXLOGF`', opts, function test( t ) {
	var y;
	var v;
	var i;

	for ( i = 0; i < 500; i++ ) {
		v = f32( ( -randu()*1e3 ) - MAXLOGF );
		y = sinhf( v );
		t.strictEqual( y, NINF, 'returns expected value' );
	}
	t.end();
});
